using System.Text.Json;
using VisionFramework;
namespace VisionEditor.Core;
public sealed partial class GraphEditorDocument {
 public void SetProcedureDisplayStyles(string flow,string id,IReadOnlyDictionary<string,RoiDisplayStyle> styles){_ = Procedure(flow).Nodes.Single(n=>n.Id==id);var copy=RoiDisplayStyles.Snapshot(styles);Edit(doc=>doc with{Procedures=doc.Procedures.Select(p=>p.Id==flow?p with{Nodes=p.Nodes.Select(n=>n.Id==id?n with{DisplayStyles=copy}:n).ToArray()}:p).ToArray()});}

 public void SetProcedureToolConfiguration(string flow,string id,Dictionary<string,JsonElement> parameters,IReadOnlyList<RoiDocument> rois,IReadOnlyCollection<string>? clearInputs=null){var p=Procedure(flow);var n=p.Nodes.Single(n=>n.Id==id);var d=registry.GetDescriptor(n);var capability=d.RoiEditor??d.Parameters.Select(p=>p.Editor).FirstOrDefault(e=>e?.Kind==ParameterEditorKind.Roi)?.Roi??throw new InvalidOperationException("工具未声明ROI能力。");RoiGeometry.ValidateForEditor(rois,capability);var values=CheckedParameters(n,parameters);var cleared=(clearInputs??[]).ToHashSet(StringComparer.Ordinal);if(cleared.Any(name=>!d.Inputs.Any(i=>i.Name==name)))throw new InvalidOperationException("清除订阅的端口无效。");var next=p with{Nodes=p.Nodes.Select(node=>node.Id==id?node with{Parameters=values,Rois=rois.Select(r=>r with{Vertices=r.Vertices?.ToArray()}).ToArray()}:node).ToArray(),Connections=p.Connections.Where(c=>c.ToNode!=id||!cleared.Contains(c.ToPort)).ToArray(),Configuration=p.Configuration with{Subscriptions=p.Configuration.Subscriptions.Where(b=>b.NodeId!=id||b.IsParameter||!cleared.Contains(b.Target)).ToArray()}};next.Configuration.Validate(next,registry);Edit(doc=>doc with{Procedures=doc.Procedures.Select(proc=>proc.Id==flow?next:proc).ToArray()});}
}
